-- ================= SECCIÓN 1. Introducción: el autogobierno parlamentario
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (4, NULL, 'seccion', '1', 'c1', 'Introducción: el autogobierno parlamentario', '<p>Las Cortes Generales, compuestas por el Congreso de los Diputados y el Senado, no son meras asambleas deliberantes. Son instituciones complejas que necesitan una estructura interna de gobierno para funcionar. Esta estructura se fundamenta en el artículo 72 de la Constitución Española, que consagra la autonomía de las Cámaras.</p><div class="uji-cita"><p><strong>Artículo 72 CE</strong> 1. Las Cámaras establecen sus propios Reglamentos, aprueban autónomamente sus presupuestos y, de común acuerdo, regulan el Estatuto del Personal de las Cortes Generales. Los Reglamentos y su reforma serán sometidos a una votación final sobre su totalidad, que requerirá la mayoría absoluta. 2. Las Cámaras eligen sus respectivos Presidentes y los demás miembros de sus Mesas. Las sesiones conjuntas serán presididas por el Presidente del Congreso y se regirán por un Reglamento de las Cortes Generales aprobado por mayoría absoluta de cada Cámara. 3. Los Presidentes de las Cámaras ejercen en nombre de las mismas todos los poderes administrativos y facultades de policía en el interior de sus respectivas sedes.</p></div><p>Este artículo es la piedra angular. Significa tres cosas fundamentales:</p><ul class="uji-lista"><li><strong>Autonomía normativa</strong> — cada Cámara dicta sus propias normas internas (Reglamento).</li><li><strong>Autonomía organizativa</strong> — cada Cámara elige a sus propios dirigentes (Presidente y Mesa).</li><li><strong>Autonomía presupuestaria y de policía</strong> — cada Cámara gestiona su dinero y mantiene el orden en su interior.</li></ul><p>La mayoría absoluta (mitad más uno de los miembros de la Cámara) es un blindaje: ningún grupo político puede cambiar las reglas del juego por sí solo si no cuenta con un consenso amplio. En el Congreso, mayoría absoluta son 176 votos de 350; en el Senado, 134 de 266.</p>', 1);
SET @seccion_id := LAST_INSERT_ID();


-- ================= SECCIÓN 2. La Mesa de la Cámara
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, orden)
VALUES (4, NULL, 'seccion', '2', 'c2', 'La Mesa de la Cámara', 2);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '2.1', '¿Qué es la Mesa?', '<p>La Mesa es el órgano rector de la Cámara. Es el "gobierno interno" del Parlamento. Toma las decisiones administrativas y de calificación que permiten que la Cámara funcione.</p><div class="uji-cita"><p><strong>Reglamento del Congreso (RC), artículo 30.1</strong> La Mesa es el órgano rector de la Cámara y ostenta la representación colegiada de ésta en los actos a que asista.</p></div><div class="uji-cita"><p><strong>Reglamento del Senado (RS), artículo 35.1</strong> La Mesa, órgano rector del Senado, actúa bajo la autoridad y dirección de su Presidente.</p></div><p>La expresión "representación colegiada" significa que cuando la Mesa asiste a un acto oficial (por ejemplo, un funeral de Estado o una recepción diplomática), representa a toda la Cámara, no solo a sus miembros individuales.</p>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '2.2', 'Composición de la Mesa', '<p>Aquí encontramos la primera gran diferencia entre ambas Cámaras:</p><ul class="uji-lista"><li><strong>Congreso</strong> — 1 Presidencia, 4 Vicepresidencias, 4 Secretarías — 9 miembros.</li><li><strong>Senado</strong> — 1 Presidencia, 2 Vicepresidencias, 4 Secretarías — 7 miembros.</li></ul><div class="uji-cita"><p><strong>RC, artículo 30.2</strong> La Mesa estará compuesta por la Presidencia del Congreso, cuatro Vicepresidencias y cuatro Secretarías.</p></div><div class="uji-cita"><p><strong>RS, artículo 5.1</strong> La Mesa estará formada por el Presidente, dos Vicepresidentes y cuatro Secretarios.</p></div><p>¿Por qué el Senado tiene menos vicepresidentes? El Senado es la Cámara de representación territorial, y su funcionamiento interno se ha diseñado históricamente con una estructura más ligera. Los dos vicepresidentes son suficientes para suplir al Presidente y para presidir las sesiones en su ausencia, mientras que las cuatro secretarías garantizan una representación plural de los distintos grupos territoriales.</p><div class="uji-cita"><p><strong>RC, artículo 30.3</strong> La Presidencia dirige y coordina la acción de la Mesa.</p></div><p>El Presidente no es un "primero entre iguales". Es quien marca la orientación de las decisiones, convoca las reuniones y dirige los debates internos de la Mesa.</p>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '2.3', 'Funciones de la Mesa (el poder real)', '<p>Las funciones de la Mesa están enumeradas en el artículo 31 del RC y en el artículo 36 del RS. Son, con diferencia, las más importantes para entender el poder de este órgano.</p><p><strong>3.1. Función organizativa y de gobierno interior</strong></p><div class="uji-cita"><p><strong>RC, artículo 31.1.1º</strong> Adoptar cuantas decisiones y medidas requieran la organización del trabajo y el régimen y gobierno interiores de la Cámara.</p></div><div class="uji-cita"><p><strong>RS, artículo 36.d</strong> Adoptar cuantas decisiones y medidas requieran la organización del trabajo y el régimen y gobierno interiores de la Cámara.</p></div><p>Esta es una cláusula abierta que otorga a la Mesa un poder muy amplio sobre la vida cotidiana del Parlamento. Decide:</p><ul class="uji-lista"><li>Los horarios de las sesiones.</li><li>La asignación de despachos a los diputados y senadores.</li><li>La contratación y gestión del personal de la Cámara.</li><li>Las medidas de seguridad dentro del recinto.</li><li>Todo lo necesario para que la Cámara funcione.</li></ul><p><strong>3.2. Función presupuestaria y financiera</strong></p><div class="uji-cita"><p><strong>RC, artículo 31.1.2º y 3º</strong> Elaborar el proyecto de Presupuesto del Congreso, dirigir y controlar su ejecución y presentar ante el Pleno de la Cámara, al final de cada ejercicio, un informe acerca de su cumplimiento. Ordenar los gastos de la Cámara, sin perjuicio de las delegaciones que pueda acordar.</p></div><div class="uji-cita"><p><strong>RS, artículo 36.e</strong> Aprobar el proyecto de Presupuesto del Senado, dirigir y controlar su ejecución y aprobar sus modificaciones y su liquidación.</p></div><p>La Mesa es la dueña del presupuesto de la Cámara. Decide:</p><ul class="uji-lista"><li>El sueldo de los diputados y senadores (dentro de los límites legales).</li><li>Las dietas por viajes y desplazamientos.</li><li>Los gastos de mantenimiento del edificio.</li><li>Los salarios del personal.</li><li>Los contratos con proveedores.</li></ul><p>El Presidente ordena los pagos (RC 32.1), pero es la Mesa quien aprueba el presupuesto y controla su ejecución.</p><p><strong>3.3. La función más importante: calificación, admisión y tramitación de escritos</strong></p><div class="uji-cita"><p><strong>RC, artículo 31.1.4º y 5º</strong> Calificar, con arreglo al Reglamento, los escritos y documentos de índole parlamentaria, así como declarar la admisibilidad o inadmisibilidad de los mismos. Decidir la tramitación de todos los escritos y documentos de índole parlamentaria, de acuerdo con las normas establecidas en este Reglamento.</p></div><div class="uji-cita"><p><strong>RS, artículo 36.c</strong> Calificar, con arreglo al Reglamento, los escritos y documentos de índole parlamentaria, así como decidir sobre su admisibilidad y tramitación.</p></div><p>¿Qué significa "calificar"? Cuando un diputado, un senador o un grupo parlamentario presenta un escrito (una proposición de ley, una pregunta al Gobierno, una solicitud de comparecencia, etc.), ese escrito llega primero a la Mesa. La Mesa examina:</p><ul class="uji-lista"><li><strong>Si cumple los requisitos formales</strong> — ¿Está escrito en el formato correcto? ¿Se ha presentado en plazo? ¿Tiene las firmas necesarias?</li><li><strong>Si es admisible</strong> — ¿La materia es competencia de la Cámara? ¿No incurre en alguna prohibición legal?</li><li><strong>Qué tramitación debe seguir</strong> — ¿Va al Pleno directamente? ¿A qué Comisión se envía? ¿Qué plazos se aplican?</li></ul><p>Si la Mesa inadmite un escrito, ese escrito muere. No puede seguir adelante. No hay recurso ante los tribunales ordinarios contra esta decisión; el único remedio es interno: la reconsideración.</p><div class="uji-cita"><p><strong>RC, artículo 31.2 (mecanismo de reconsideración)</strong> Si un miembro de la Cámara o un Grupo Parlamentario discrepare de la decisión adoptada por la Mesa en el ejercicio de las funciones a que se refieren los puntos 4.º y 5.º del apartado anterior, podrá solicitar su reconsideración. La Mesa decidirá definitivamente, oída la Junta de Portavoces, mediante resolución motivada.</p></div><div class="uji-cita"><p><strong>RS, artículo 36.2</strong> Cuando una decisión adoptada por la Mesa, en el ejercicio de las funciones a que se refiere el punto c) del número anterior, afecte directamente a un Senador o a un Grupo parlamentario, éstos podrán solicitar su reconsideración. La Mesa decidirá mediante resolución motivada.</p></div><p>Es decir: si la Mesa inadmite un escrito, el diputado o grupo afectado puede pedir que la Mesa lo reconsidere. Entonces la Mesa vuelve a estudiarlo, oye a la Junta de Portavoces (los representantes de todos los grupos) y decide definitivamente, pero debe explicar por escrito las razones de su decisión (resolución motivada).</p><p><strong>3.4. Función de programación y calendario</strong></p><div class="uji-cita"><p><strong>RC, artículo 31.1.6º</strong> Programar las líneas generales de actuación de la Cámara, fijar el calendario de actividades del Pleno y de las Comisiones para cada período de sesiones y coordinar los trabajos de sus distintos órganos, todo ello previa audiencia de la Junta de Portavoces.</p></div><div class="uji-cita"><p><strong>RS, artículo 36.b</strong> Determinar el calendario de actividades del Pleno y de las Comisiones para cada período de sesiones.</p></div><p>La Mesa decide qué días se reúne el Pleno, qué días se reúnen las Comisiones, y qué asuntos se tratan en cada sesión. Pero no puede hacerlo sola: debe oír previamente a la Junta de Portavoces. Es un primer ejemplo de la relación entre estos dos órganos.</p><p><strong>3.5. Funciones adicionales en el Senado</strong></p><p>El Reglamento del Senado añade funciones específicas que no están en el del Congreso:</p><div class="uji-cita"><p><strong>RS, artículo 36.f</strong> Aprobar las normas que, en ejercicio de la autonomía del Senado, adapten las disposiciones generales del ordenamiento jurídico en materia presupuestaria, de control, de contabilidad y de contratación a la organización y funcionamiento de la Cámara.</p></div><div class="uji-cita"><p><strong>RS, artículo 36.g</strong> Aprobar las normas y adoptar las medidas que resulten precisas para garantizar la transparencia de la actividad de la Cámara y el derecho de acceso a la información pública del Senado.</p></div><p>Esto significa que la Mesa del Senado tiene competencias normativas propias: puede dictar normas internas sobre cómo se gestiona el presupuesto, cómo se controlan las cuentas, cómo se contratan servicios, y cómo se garantiza la transparencia y el acceso a la información.</p><p><strong>3.6. Función residual (cláusula de cierre)</strong></p><div class="uji-cita"><p><strong>RC, artículo 31.1.7º</strong> Cualesquiera otras que le encomiende el presente Reglamento y las que no estén atribuidas a un órgano específico.</p></div><div class="uji-cita"><p><strong>RS, artículo 36.h</strong> Cualesquiera otras que le confieran las leyes y el presente Reglamento.</p></div><p>Esta cláusula asegura que no haya vacíos de poder. Si algo no está atribuido expresamente a otro órgano (Pleno, Presidencia, Junta de Portavoces, etc.), la Mesa es la que decide.</p>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '2.4', 'La elección de la Mesa', '<p>La Mesa se elige en la sesión constitutiva de la Cámara, que es la primera reunión tras unas elecciones generales.</p><p><strong>4.1. El procedimiento en el Congreso (arts. 36, 37 y 38 RC)</strong></p><div class="uji-cita"><p><strong>RC 37.1 (elección del Presidente)</strong> En la elección de la Presidencia, se escribirá sólo un nombre en la papeleta. Resultará elegida la persona que obtenga el voto de la mayoría absoluta de los miembros de la Cámara. Si nadie obtuviera en primera votación dicha mayoría, se repetirá la elección entre quienes hayan alcanzado las dos mayores votaciones y se elegirá a quien obtenga más votos.</p></div><p>Explicación: la primera votación exige mayoría absoluta (176 votos). Si nadie la alcanza, se hace una segunda votación solo entre los dos más votados de la primera vuelta. En esa segunda vuelta, gana el que obtenga más votos, sea cual sea esa cifra (pueden ser 151 frente a 149). Este sistema asegura que el Presidente tenga un respaldo muy amplio si es elegido en primera vuelta, pero evita un bloqueo total si nadie alcanza la mayoría absoluta.</p><div class="uji-cita"><p><strong>RC 37.2 (elección de Vicepresidentes y Secretarios)</strong> Las cuatro Vicepresidencias se elegirán simultáneamente. Se escribirá, asimismo, sólo un nombre en la papeleta. Resultarán elegidas, por orden sucesivo, las cuatro personas que obtengan mayor número de votos. En la misma forma serán elegidas las cuatro Secretarías.</p></div><p>Explicación: todos los diputados votan a la vez para Vicepresidentes y para Secretarios. En cada papeleta solo se puede escribir un nombre. Los cuatro candidatos más votados son elegidos Vicepresidentes (primero, segundo, tercero y cuarto según el número de votos). Lo mismo para los cuatro Secretarios.</p><div class="uji-cita"><p><strong>RC 37.3 (empates)</strong> Si en alguna votación se produjere empate, se celebrarán sucesivas votaciones entre las candidaturas igualadas en votos hasta que el empate quede dirimido.</p></div><div class="uji-cita"><p><strong>RC 36.2 (nueva elección por cambios en la composición)</strong> Se procederá a nueva elección de la Mesa cuando las sentencias recaídas en los recursos contencioso-electorales supusieran cambio en la titularidad de más del 10 por 100 de los escaños.</p></div><p>Si recursos judiciales anulan la elección de más del 10% de los diputados, se repite la elección de la Mesa.</p><div class="uji-cita"><p><strong>RC 38 (vacantes)</strong> Las vacantes que se produzcan en la Mesa durante la legislatura serán cubiertas por elección del Pleno en la forma establecida en el artículo anterior, adaptado en sus previsiones a la realidad de las vacantes a cubrir.</p></div><p>Si alguien de la Mesa fallece, dimite o pierde su escaño, se elige un sustituto con el mismo procedimiento.</p><p><strong>4.2. El procedimiento en el Senado (arts. 5 a 10 RS)</strong></p><p>El procedimiento es similar al del Congreso, pero con tres diferencias clave:</p><p><strong>Diferencia 1: composición de la Mesa (RS 5.1)</strong></p><div class="uji-cita"><p><strong>RS 5.1</strong> La Mesa estará formada por el Presidente, dos Vicepresidentes y cuatro Secretarios.</p></div><p>Solo dos vicepresidentes, no cuatro.</p><p><strong>Diferencia 2: elección de Vicepresidentes (RS 8.1)</strong></p><div class="uji-cita"><p><strong>RS 8.1</strong> Los dos Vicepresidentes se elegirán simultáneamente, sin que cada Senador pueda escribir más de un nombre en la papeleta. Resultarán elegidos, por orden correlativo, los dos que obtengan mayor número de votos.</p></div><p><strong>Diferencia 3: elección de Secretarios (RS 9) — ¡la más importante!</strong></p><div class="uji-cita"><p><strong>RS 9</strong> Para la elección de los cuatro Secretarios, los Senadores escribirán sólo dos nombres en la papeleta y resultarán elegidos, por orden de votos, los cuatro que obtengan mayor número.</p></div><p>Mientras que en el Congreso cada diputado vota un solo nombre para Secretario, en el Senado cada senador vota dos nombres. Esto permite una representación más amplia y plural: un senador puede apoyar a dos candidatos diferentes, lo que facilita que grupos territoriales más pequeños tengan representación en la Secretaría.</p><div class="uji-cita"><p><strong>RS 10 (validez de papeletas)</strong> Cuando una papeleta contuviere más nombres de los necesarios, únicamente se computarán, por su orden, los que correspondan... La papeleta que contuviere menos nombres de los necesarios será válida.</p></div><p>Si alguien escribe tres nombres cuando solo se necesitan dos, solo se cuentan los dos primeros. Si escribe solo uno, es válido. Si escribe nombres no propuestos o cualquier otra manifestación, es nula.</p>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '2.5', 'Reuniones y personal de apoyo', '<div class="uji-cita"><p><strong>RC, artículo 35.1</strong> La Mesa se reunirá a convocatoria de la Presidencia y estará asesorada por la Secretaria o Secretario General, que redactará el acta de las sesiones y cuidará, bajo la dirección de la Presidencia, de la ejecución de los acuerdos.</p></div><div class="uji-cita"><p><strong>RS, artículo 35.2</strong> Estará asistida y asesorada por el Letrado Mayor, que es el Jefe de los Servicios y responde ante el Presidente de la Cámara.</p></div><p>El Secretario General del Congreso y el Letrado Mayor del Senado son funcionarios de carrera (no políticos), especializados en derecho parlamentario. Su opinión técnica es muy respetada y suele ser decisiva en cuestiones de interpretación del Reglamento.</p><div class="uji-cita"><p><strong>RC 35.3 (nombramiento del Secretario General del Congreso)</strong> El nombramiento de la Secretaria o Secretario General se realizará por la Mesa del Congreso, a propuesta de su Presidencia, entre los letrados y letradas de las Cortes con más de cinco años de servicios efectivos.</p></div><p><strong>Reuniones telemáticas (RC 35.2 y RS 36.3)</strong></p><p>El Congreso permite la participación telemática de miembros de la Mesa solo en casos excepcionales (embarazo, maternidad, paternidad, motivos de salud, etc.) y con declaración responsable del interesado. El Senado, en cambio, permite las reuniones telemáticas de la Mesa de forma más amplia (RS 36.3: "Las reuniones de la Mesa se podrán celebrar telemáticamente").</p>', 5);

-- ================= SECCIÓN 3. La Presidencia de la Cámara
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, orden)
VALUES (4, NULL, 'seccion', '3', 'c3', 'La Presidencia de la Cámara', 3);
