INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '3.1', '¿Quién es el Presidente de la Cámara?', '<p>El Presidente es la máxima autoridad individual de la Cámara. Es elegido por sus compañeros diputados o senadores en la sesión constitutiva. Representa a la Cámara, dirige los debates, mantiene el orden y ejerce poderes administrativos y de policía dentro del recinto.</p><p>Su mandato termina por:</p><ul class="uji-lista"><li>Fallecimiento.</li><li>Dimisión.</li><li>Pérdida de la condición de diputado o senador (por sentencia judicial firme).</li><li>Disolución de las Cortes (aunque sigue en funciones hasta la nueva sesión constitutiva).</li></ul><p>No puede ser cesado durante la legislatura por ninguna institución externa.</p>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '3.2', 'Funciones del Presidente del Congreso (art. 32 RC)', '<div class="uji-cita"><p><strong>RC, artículo 32.1</strong> La Presidencia del Congreso ostenta la representación de la Cámara, asegura la buena marcha de los trabajos, dirige los debates, mantiene el orden de los mismos y ordena los pagos, sin perjuicio de las delegaciones que pueda conferir.</p></div><p>Explicación de cada función:</p><ul class="uji-lista"><li><strong>Representación de la Cámara</strong> — el Presidente es la cara visible del Congreso ante el Rey, el Gobierno, los tribunales, las demás instituciones y la opinión pública.</li><li><strong>Buena marcha de los trabajos</strong> — coordina las actividades de la Cámara, asegurando que todo funcione según lo previsto.</li><li><strong>Dirige los debates</strong> — durante los plenos, concede la palabra, la retira si alguien se sale del tema o insulta, decide sobre las interrupciones y llama al orden.</li><li><strong>Mantiene el orden</strong> — puede expulsar a diputados que perturben gravemente la sesión (aunque la suspensión temporal requiere acuerdo del Pleno, según RC 101).</li><li><strong>Ordena los pagos</strong> — ejecuta el presupuesto aprobado por la Mesa.</li></ul><div class="uji-cita"><p><strong>RC, artículo 32.2 (función de interpretar y suplir el Reglamento)</strong> Corresponde a la Presidencia cumplir y hacer cumplir el Reglamento, interpretándolo en los casos de duda y supliéndolo en los de omisión. Cuando en el ejercicio de esta función supletoria se propusiera dictar una resolución de carácter general, deberá mediar el parecer favorable de la Mesa y de la Junta de Portavoces.</p></div><p>Explicación: el Presidente es el "guardián" del Reglamento. Si hay una duda sobre cómo aplicar una norma, él la interpreta. Si el Reglamento no dice nada sobre una situación nueva (por ejemplo, cómo votar telemáticamente durante una pandemia, que no estaba previsto cuando se redactó el Reglamento en 1982), el Presidente puede tomar una decisión para "suplir" esa laguna. Pero si esa decisión es de carácter general (es decir, una norma que valdrá para todos los casos futuros, no solo para un caso concreto), entonces necesita el parecer favorable de la Mesa y de la Junta de Portavoces. No puede legislar por su cuenta; debe contar con el consenso de los grupos.</p><div class="uji-cita"><p><strong>RC, artículo 32.3</strong> La Presidencia desempeña, asimismo, todas las demás funciones que le confieren la Constitución, las leyes y el presente Reglamento.</p></div>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '3.3', 'Funciones del Presidente del Senado (art. 37 RS)', '<p>El Reglamento del Senado enumera las funciones de su Presidente con más detalle:</p><div class="uji-cita"><p><strong>RS, artículo 37</strong> Corresponde al Presidente del Senado: 1. Ser el Portavoz de la Cámara y su representante nato en todos los actos oficiales. 2. Convocar y presidir las sesiones del Pleno del Senado, mantener el orden de las discusiones, dirigir los debates y convocar y presidir la Mesa del Senado. 3. Convocar y presidir, cuando lo considere conveniente, cualquier Comisión del Senado. 4. Fijar el orden del día del Pleno del Senado, de acuerdo con la Mesa y oída la Junta de Portavoces. 5. Mantener las comunicaciones con el Gobierno y las autoridades. 6. Firmar, con uno de los Secretarios, los mensajes motivados que el Senado haya de dirigir, así como las actas de la Mesa, del Pleno y de la Diputación Permanente y, junto con uno de los Vicepresidentes, las actas de la Junta de Portavoces. 7. Interpretar el Reglamento. 8. Suplir, de acuerdo con la Mesa de la Comisión del Reglamento, las lagunas de éste. 9. Velar por la observancia del Reglamento, de la cortesía y de los usos parlamentarios. 10. Aplicar las medidas relativas a disciplina parlamentaria. 11. Las demás facultades previstas en la Constitución, las leyes y este Reglamento.</p></div><p>Comparación con el Congreso: la diferencia más notable está en la función supletoria. En el Congreso, el Presidente suple las lagunas del Reglamento con el parecer favorable de la Mesa y la Junta de Portavoces. En el Senado, el Presidente suple de acuerdo con la Mesa de la Comisión del Reglamento (una Comisión específica del Senado, no con la Junta de Portavoces).</p>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '3.4', 'Poderes administrativos y de policía', '<div class="uji-cita"><p><strong>CE, artículo 72.3</strong> Los Presidentes de las Cámaras ejercen en nombre de las mismas todos los poderes administrativos y facultades de policía en el interior de sus respectivas sedes.</p></div><div class="uji-cita"><p><strong>RS, artículo 38</strong> El Presidente ejerce la autoridad suprema de la Cámara en el Palacio del Senado y los demás edificios que de éste dependen; dicta cuantas medidas sean necesarias para el buen orden dentro de su recinto y da las órdenes oportunas a los funcionarios y agentes del orden.</p></div><div class="uji-cita"><p><strong>RS, artículo 39</strong> El Presidente tomará las medidas necesarias respecto de las personas del público que perturben de cualquier modo el orden en las tribunas o galerías de la Cámara pudiendo, además, ordenar su expulsión en el acto y que los servicios de Seguridad de la Cámara levanten las oportunas diligencias por si los actos producidos pudieran ser constitutivos de delito o falta.</p></div><p>Explicación: dentro del Palacio del Congreso o del Senado, el Presidente es la máxima autoridad, incluso por encima de la policía nacional si hiciera falta. Puede:</p><ul class="uji-lista"><li>Expulsar al público que moleste.</li><li>Ordenar la detención de alguien que cometa un delito dentro del recinto.</li><li>Gestionar el personal y los recursos materiales.</li><li>Dictar instrucciones a los funcionarios y agentes de seguridad.</li></ul>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '3.5', 'Los Vicepresidentes', '<div class="uji-cita"><p><strong>RC, artículo 33</strong> Las Vicepresidencias, por su orden, sustituyen a la Presidencia, ejerciendo sus funciones en caso de vacante, ausencia o imposibilidad de ésta. Desempeñan, además, cualesquiera otras funciones que les encomienden la Presidencia o la Mesa.</p></div><div class="uji-cita"><p><strong>RS, artículo 40</strong> Los Vicepresidentes, por su orden, sustituirán al Presidente, ejerciendo sus funciones en caso de vacante, ausencia o imposibilidad de éste.</p></div><div class="uji-cita"><p><strong>RS, artículo 43.3 (función adicional en el Senado)</strong> Las actas de las reuniones de la Junta de Portavoces serán firmadas por el Presidente del Senado y uno de los Vicepresidentes.</p></div><p>Los Vicepresidentes son sustitutos del Presidente (primero el Vicepresidente primero, luego el segundo, etc.). Además, pueden realizar otras funciones que les encomienden el Presidente o la Mesa.</p>', 5);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '3.6', 'Los Secretarios', '<div class="uji-cita"><p><strong>RC, artículo 34</strong> Las Secretarías supervisan y autorizan, con el visto bueno de la Presidencia, las actas de las sesiones plenarias, de la Mesa y de la Junta de Portavoces, así como las certificaciones que hayan de expedirse; asisten a la Presidencia en las sesiones para asegurar el orden en los debates y la corrección en las votaciones; colaboran al normal desarrollo de los trabajos de la Cámara según las disposiciones de la Presidencia; ejercen, además, cualesquiera otras funciones que les encomiende la Presidencia o la Mesa.</p></div><div class="uji-cita"><p><strong>RS, artículo 41</strong> Corresponden a los Secretarios del Senado las siguientes funciones: 1. Redactar y autorizar las actas de las sesiones plenarias, que deberán ir firmadas por dos de ellos, con el visto bueno del Presidente. 2. Dar cuenta de todas las comunicaciones y documentos que se remitan al Senado, extendiendo y firmando las resoluciones que recaigan. 3. Autorizar cuantas comunicaciones y certificaciones oficiales se expidan por la Secretaría. 4. Computar los resultados de las votaciones del Senado. 5. Firmar uno de ellos con el Presidente los mensajes motivados previstos en el artículo 90.2 de la Constitución.</p></div><div class="uji-cita"><p><strong>RS, artículo 42</strong> La Mesa del Senado podrá, en cualquier momento, distribuir el desempeño de las funciones enumeradas en el artículo anterior entre los Secretarios.</p></div><p>Los Secretarios son los garantes de la corrección formal. Redactan las actas, cuentan los votos, expiden certificaciones, y firman documentos oficiales. En el Senado, la Mesa puede redistribuir estas funciones entre los cuatro secretarios según lo considere oportuno.</p>', 6);

-- ================= SECCIÓN 4. La Junta de Portavoces
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, orden)
VALUES (4, NULL, 'seccion', '4', 'c4', 'La Junta de Portavoces', 4);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '4.1', '¿Qué es la Junta de Portavoces?', '<p>La Junta de Portavoces es el órgano de consenso político de la Cámara. No es un órgano decisorio en sí mismo (no vota leyes), pero su opinión es preceptiva (obligatoria) para muchas decisiones importantes de la Mesa y del Presidente. Aquí es donde los portavoces de los grupos parlamentarios se sientan a negociar el calendario, el orden del día y las grandes cuestiones de funcionamiento.</p>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '4.2', 'Composición (RC 39 y RS 43)', '<div class="uji-cita"><p><strong>RC, artículo 39.1</strong> Las personas designadas para las portavocías de los Grupos Parlamentarios constituyen la Junta de Portavoces, que se reunirá bajo la presidencia del Presidente o Presidenta del Congreso.</p></div><div class="uji-cita"><p><strong>RC, artículo 39.3</strong> A las reuniones de la Junta deberán asistir, al menos, una de las Vicepresidencias, una de las Secretarías de la Cámara y el Secretario o Secretaria General. Los y las portavoces o sus suplentes podrán acompañarse por un miembro de su Grupo que no tendrá derecho a voto.</p></div><div class="uji-cita"><p><strong>RC, artículo 39.2</strong> De las reuniones de la Junta se dará cuenta al Gobierno para que envíe, si lo estima oportuno, a quien lo represente, acompañándose, en su caso, por persona que le asista.</p></div><div class="uji-cita"><p><strong>RS, artículo 43.1</strong> La Junta de Portavoces estará integrada por el Presidente de la Cámara, que la convoca y preside, y por los Portavoces de los Grupos parlamentarios existentes en cada momento o miembros de su Grupo en quienes deleguen la asistencia.</p></div><div class="uji-cita"><p><strong>RS, artículo 43.2</strong> A las reuniones de este órgano, que podrán celebrarse telemáticamente, además de los Portavoces de los diferentes Grupos parlamentarios, podrán asistir los Vicepresidentes del Senado, un representante del Gobierno, que podrá estar acompañado por persona que le asista, y hasta dos representantes de los Grupos territoriales de un mismo Grupo parlamentario, designados por su Portavoz. Asimismo, cuando se trate de deliberar sobre alguna materia que afecte especialmente a una Comunidad Autónoma, el Presidente lo comunicará a los Portavoces de los Grupos parlamentarios en los que existieran Grupos territoriales, a efectos de que también puedan asistir los representantes de estos últimos.</p></div><p>Explicación de la composición:</p><ul class="uji-lista"><li><strong>Presidente de la Cámara</strong> — la preside y la convoca.</li><li><strong>Portavoces de los Grupos Parlamentarios</strong> — son los miembros con derecho a voto.</li><li><strong>Vicepresidencias y Secretarías</strong> — asisten sin voto (al menos uno de cada en el Congreso; en el Senado pueden asistir los Vicepresidentes).</li><li><strong>Secretario General / Letrado Mayor</strong> — asesoran técnicamente.</li><li><strong>Representante del Gobierno</strong> — puede asistir, pero sin voto.</li><li><strong>En el Senado, representantes de los Grupos Territoriales</strong> — pueden asistir cuando se traten asuntos que afecten a una Comunidad Autónoma concreta.</li></ul>', 2);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '4.3', 'El voto ponderado (RC 39.4 y RS 43)', '<div class="uji-cita"><p><strong>RC, artículo 39.4</strong> Las decisiones de la Junta de Portavoces se adoptarán siempre en función del criterio de voto ponderado.</p></div><p>Explicación: no es "un portavoz, un voto". El voto de cada portavoz vale en proporción al número de diputados o senadores que tiene su grupo. Por ejemplo:</p><ul class="uji-lista"><li>El portavoz del Grupo Socialista (120 diputados) tendrá un peso mucho mayor que el portavoz del Grupo Mixto (5 diputados).</li><li>Esto evita que un partido minúsculo pueda bloquear decisiones con el mismo poder que uno grande.</li></ul><p>En la práctica, se busca el consenso (unanimidad o casi unanimidad), pero si hay que votar, se aplica esta ponderación.</p>', 3);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '4.4', 'Convocatoria (RC 39.1)', '<div class="uji-cita"><p><strong>RC, artículo 39.1</strong> El Presidente la convocará, a iniciativa propia o a petición de dos Grupos Parlamentarios o de la quinta parte de los miembros de la Cámara.</p></div><p>La quinta parte de los miembros del Congreso son unos 70 diputados; en el Senado, unos 53 senadores. Esto permite que tanto la mayoría como las minorías puedan solicitar una reunión.</p>', 4);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '4.5', 'Funciones y ámbitos en los que debe ser oída', '<p>La Junta de Portavoces no decide directamente, pero debe ser oída (consultada) en varias materias clave:</p><p><strong>a) Calendario de plenos y comisiones (RC 31.1.6º y RS 36.b)</strong></p><p>La Mesa fija el calendario, pero previa audiencia de la Junta de Portavoces. La Junta no veta, pero su opinión es obligatoria.</p><p><strong>b) Interpretaciones y supletoriedad del Reglamento por el Presidente (RC 32.2)</strong></p><p>Cuando el Presidente quiere dictar una resolución de carácter general para suplir una laguna del Reglamento, necesita el parecer favorable de la Mesa y de la Junta de Portavoces.</p><p><strong>c) Reconsideración de decisiones de la Mesa sobre admisión o tramitación (RC 31.2)</strong></p><p>Cuando la Mesa reconsidera una decisión sobre admisión de un escrito, oye a la Junta de Portavoces antes de decidir definitivamente.</p><p><strong>d) Orden del día (RS 44.b)</strong></p><p>En el Senado, la Junta de Portavoces es oída para fijar el orden del día de las sesiones plenarias.</p><p><strong>e) Criterios para ordenar debates (RS 44.c)</strong></p><p><strong>f) Normas interpretativas o supletorias (RS 44.d)</strong></p>', 5);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '4.6', 'Declaraciones Institucionales (solo Senado, art. 44 bis RS)', '<div class="uji-cita"><p><strong>RS, artículo 44 bis</strong> 1. A iniciativa de uno o varios Grupos parlamentarios, la Junta de Portavoces, por unanimidad, podrá someter al Pleno propuestas de Declaración Institucional sobre asuntos de interés general. 2. Durante la sesión plenaria, uno de los Secretarios dará lectura a la Declaración Institucional, sin que dé lugar a debate ni votación.</p></div><p>Explicación: el Senado puede hacer declaraciones institucionales sobre temas de interés general (por ejemplo, condenar un atentado terrorista, apoyar a un colectivo, etc.). La Junta de Portavoces debe aprobarlas por unanimidad (todos los grupos de acuerdo). Luego, en el Pleno, un Secretario la lee, pero no hay debate ni votación. Es un manifiesto de la Cámara.</p>', 6);

-- ================= SECCIÓN 5. La Sesión Constitutiva
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, orden)
VALUES (4, NULL, 'seccion', '5', 'c5', 'La Sesión Constitutiva', 5);
SET @seccion_id := LAST_INSERT_ID();

INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '5.1', 'La sesión constitutiva del Congreso (arts. 1-5 RC)', '<p>La sesión constitutiva es la primera reunión del Congreso tras unas elecciones generales. Es un acto formal, cargado de simbolismo.</p><div class="uji-cita"><p><strong>RC, artículo 1</strong> Celebradas elecciones generales al Congreso, éste se reunirá, de acuerdo con lo preceptuado en el artículo 68.6 de la Constitución, en sesión constitutiva el día y hora señalados en el Real Decreto de convocatoria.</p></div><div class="uji-cita"><p><strong>RC, artículo 2</strong> La sesión constitutiva será presidida inicialmente por la diputada o diputado electos de mayor edad presente en la Cámara, con la asistencia de los dos más jóvenes, que ocuparán las Secretarías.</p></div><p>Esta es la llamada "Mesa de edad". La preside el diputado más mayor, asistido por los dos más jóvenes como secretarios. Es una tradición parlamentaria europea que simboliza la unión de la experiencia (el mayor) y el futuro (los jóvenes). También garantiza que la presidencia inicial sea neutral, ya que nadie sabe de antemano quién será el más mayor.</p><div class="uji-cita"><p><strong>RC, artículo 3.1</strong> La Presidencia declarará abierta la sesión y una de las personas que ocupe la Secretaría dará lectura al Real Decreto de convocatoria, a la relación de cargos electos y a los recursos contencioso-electorales interpuestos, con indicación de aquellos miembros electos de la Cámara que pudieran quedar afectados por la resolución de los mismos.</p></div><div class="uji-cita"><p><strong>RC, artículo 3.2</strong> Se procederá seguidamente a la elección de la Mesa del Congreso, de acuerdo con el procedimiento previsto en el artículo 37 de este Reglamento.</p></div><div class="uji-cita"><p><strong>RC, artículo 4.1</strong> Concluidas las votaciones, las diputadas y diputados elegidos ocuparán sus puestos. La Presidenta o Presidente prestará y solicitará al resto de miembros de la Cámara el juramento o promesa de acatar la Constitución, a cuyo efecto se efectuará su llamamiento por orden alfabético. La Presidencia declarará constituido el Congreso, levantando seguidamente la sesión.</p></div><p><strong>La diferencia entre jurar y prometer</strong></p><ul class="uji-lista"><li>Jurar tiene connotaciones religiosas (ante Dios o bajo juramento).</li><li>Prometer es una fórmula laica.</li><li>Ambos son igualmente válidos. Es una cuestión de convicciones personales o ideológicas. Algunos partidos republicanos o laicos prefieren "prometo" en lugar de "juro".</li></ul><div class="uji-cita"><p><strong>RC, artículo 4.2</strong> La constitución del Congreso será comunicada por el Presidente o la Presidenta al Rey o a la Reina, al Senado y al Gobierno.</p></div><div class="uji-cita"><p><strong>RC, artículo 5</strong> Dentro del plazo de los quince días siguientes a la celebración de la sesión constitutiva, tendrá lugar la solemne sesión de apertura de la legislatura.</p></div><p>Esta sesión solemne es conjunta con el Senado y presidida por el Rey, que pronuncia un discurso sobre el inicio de la legislatura.</p>', 1);
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, titulo, contenido_html, orden)
VALUES (4, @seccion_id, 'epigrafe', '5.2', 'La constitución del Senado (arts. 1-14 RS)', '<p>El Senado tiene un procedimiento más complejo, con la peculiaridad de la constitución interina.</p><div class="uji-cita"><p><strong>RS, artículo 2</strong> 1. En el día que, dentro del plazo legal previsto, señale el Decreto de convocatoria de elecciones, los Senadores se reunirán en el Palacio del Senado para celebrar Junta Preparatoria. 2. El que figure primero en la lista de presentación de credenciales ocupará la Presidencia, declarará abierta la sesión y dispondrá que por el Letrado Mayor se lea la convocatoria de la Cámara. Asimismo ordenará que se dé cuenta de las impugnaciones presentadas contra la proclamación de Senadores, si las hubiere.</p></div><p>Diferencia con el Congreso: en el Senado, el primer presidente no es el más mayor, sino el que primero aparece en la lista de presentación de credenciales (es decir, el que antes presentó sus papeles). Luego, tras esta lectura, se forma la Mesa de edad.</p><div class="uji-cita"><p><strong>RS, artículo 3</strong> Acto continuo se formará una Mesa que presidirá el Senador de más edad de entre los presentes y de la que serán Secretarios los cuatro más jóvenes.</p></div><div class="uji-cita"><p><strong>RS, artículo 4.1 (la gran diferencia: constitución interina)</strong> Tras la formación de la Mesa de edad, el Senado procederá a constituirse en forma definitiva, salvo que las impugnaciones formuladas contra la proclamación de Senadores de elección directa afectase a un veinte por ciento o más de los escaños que éstos suponen en el total de la Cámara, en cuyo caso su constitución será interina, situación que se prolongará hasta que las impugnaciones resueltas confirmen la proclamación de Senadores de elección directa en número no inferior al ochenta por ciento de los mismos.</p></div><div class="uji-cita"><p><strong>RS, artículo 4.2 (funciones del Senado interino)</strong> Cuando el Senado esté constituido interinamente, sólo se ocupará del examen de las incompatibilidades, salvo que, por iniciativa parlamentaria o como consecuencia de las comunicaciones del Gobierno, se estimase indispensable deliberar acerca de algún otro tema. Para el ejercicio de aquella iniciativa se requerirá una proposición firmada por un Grupo parlamentario o por veinticinco Senadores.</p></div><p>Explicación: si más del 20% de los senadores elegidos directamente están impugnados judicialmente (por recursos contra los resultados electorales), el Senado se constituye de forma interina (provisional). En ese estado, solo puede ocuparse del examen de incompatibilidades (comprobar que los senadores no tengan otros cargos prohibidos), a menos que haya un acuerdo unánime o casi unánime para tratar otro tema de carácter indispensable. Una vez resueltas las impugnaciones y confirmados al menos el 80% de los senadores, el Senado se constituye definitivamente.</p><div class="uji-cita"><p><strong>RS, artículo 5.2 (confirmación de la Mesa interina)</strong> Los miembros de la Mesa interina se entenderán confirmados en sus respectivos cargos cuando el Senado se constituya definitivamente, salvo petición, por un Grupo parlamentario como mínimo, de que se proceda a las correspondientes elecciones.</p></div><p>Si la Mesa interina ha sido elegida y luego el Senado se constituye definitivamente, esa Mesa sigue siendo la misma, a menos que un Grupo Parlamentario pida repetir las elecciones.</p><div class="uji-cita"><p><strong>RS, artículo 11 (juramento o promesa en el Senado)</strong> 1. Tras la elección definitiva o tras la confirmación de la Mesa, los Senadores deberán prestar juramento o promesa de acatamiento a la Constitución. 2. El Presidente de la Mesa de edad o el de la interina, según corresponda, o un Vicepresidente, tomará la declaración de acatamiento al que resulte elegido o confirmado como Presidente en la constitución definitiva de la Cámara, y éste, a su vez, a todos los Senadores, empezando por los Vicepresidentes y Secretarios y continuando por orden alfabético por los restantes. 3. A tales efectos, se leerá la fórmula siguiente: "¿Juráis o prometéis acatar la Constitución?" Los Senadores se acercarán sucesivamente ante la Presidencia para hacer la declaración, contestando "sí, juro" o "sí, prometo".</p></div><div class="uji-cita"><p><strong>RS, artículo 14</strong> Constituido definitivamente el Senado, su Presidente lo comunicará oficialmente al Rey, al Congreso de los Diputados y al Gobierno. También lo comunicará a las Asambleas legislativas o, en su defecto, a los órganos colegiados superiores de las Comunidades Autónomas.</p></div>', 2);

-- ================= SECCIÓN 6. Síntesis Comparativa
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (4, NULL, 'seccion', '6', 'c6', 'Síntesis Comparativa', '<p>Tabla comparativa entre el Congreso y el Senado en los aspectos vistos en este tema:</p><ul class="uji-lista"><li><strong>Miembros de la Mesa</strong> — Congreso: 9 (Presidente + 4 Vicepresidentes + 4 Secretarios). Senado: 7 (Presidente + 2 Vicepresidentes + 4 Secretarios).</li><li><strong>Elección del Presidente</strong> — Congreso: mayoría absoluta en primera vuelta, o mayoría simple entre los dos más votados en segunda vuelta. Senado: igual sistema.</li><li><strong>Elección de Vicepresidentes</strong> — Congreso: 4, cada elector vota 1 nombre. Senado: 2, cada elector vota 1 nombre.</li><li><strong>Elección de Secretarios</strong> — Congreso: 4, cada elector vota 1 nombre. Senado: 4, cada elector vota 2 nombres.</li><li><strong>Presidente inicial (Mesa de edad)</strong> — Congreso: el diputado de más edad. Senado: el primero en la lista de credenciales (luego se forma la Mesa de edad con el senador de más edad).</li><li><strong>Constitución</strong> — Congreso: siempre definitiva. Senado: puede ser interina si el 20% o más de los senadores de elección directa están impugnados.</li><li><strong>Función supletoria del Presidente</strong> — Congreso: necesita el parecer favorable de la Mesa y la Junta de Portavoces. Senado: necesita el acuerdo de la Mesa de la Comisión del Reglamento.</li><li><strong>Reuniones telemáticas de la Mesa</strong> — Congreso: excepcionales, con justificación. Senado: permitidas de forma más amplia (art. 36.3 RS).</li><li><strong>Voto ponderado en la Junta de Portavoces</strong> — Congreso: sí (RC 39.4). Senado: sí (RS 43).</li><li><strong>Asistencia de representantes del Gobierno a la Junta</strong> — Congreso: sí, sin voto (RC 39.2). Senado: sí, sin voto (RS 43.2).</li><li><strong>Grupos Territoriales en la Junta de Portavoces</strong> — Congreso: no existe esta figura. Senado: sí, hasta dos representantes por grupo (RS 43.2).</li><li><strong>Declaraciones Institucionales</strong> — Congreso: no existe esta figura. Senado: sí, por unanimidad de la Junta, sin debate ni votación en el Pleno (RS 44 bis).</li></ul>', 6);
SET @seccion_id := LAST_INSERT_ID();


-- ================= SECCIÓN 7. Conclusión Final
INSERT INTO opouj_wp_uji_nodos (tema_id, parent_id, tipo, numero, color_clase, titulo, contenido_html, orden)
VALUES (4, NULL, 'seccion', '7', 'c1', 'Conclusión Final', '<p>Las Cortes Generales no son solo un hemiciclo donde se votan leyes. Son organizaciones complejas que necesitan un gobierno interno para funcionar. Ese gobierno interno se articula en tres órganos con roles diferenciados:</p><ul class="uji-lista"><li><strong>1. La Mesa</strong> — es el órgano rector, el "gobierno de la Cámara". Decide qué iniciativas viven o mueren (calificación y admisión), gestiona el presupuesto y fija el calendario. Está compuesta por el Presidente, Vicepresidentes y Secretarios.</li><li><strong>2. La Presidencia</strong> — es la máxima autoridad individual. Representa a la Cámara, dirige los debates, mantiene el orden, interpreta y suple el Reglamento. Dentro del edificio parlamentario, es la autoridad suprema con poderes de policía.</li><li><strong>3. La Junta de Portavoces</strong> — es el órgano de consenso político. Reúne a los portavoces de los grupos parlamentarios, decide por voto ponderado, y debe ser oída para el calendario, el orden del día y las interpretaciones generales del Reglamento.</li></ul><p>El Congreso y el Senado comparten esta estructura tripartita, pero no son idénticos. El Senado tiene una Mesa más pequeña (7 miembros frente a 9), vota con dos nombres para elegir a los secretarios (el Congreso vota uno), puede constituirse de forma interina si hay muchas impugnaciones, y permite la participación de Grupos Territoriales en su Junta de Portavoces.</p><p>Todo este sistema tiene su fundamento último en el artículo 72 de la Constitución, que consagra la autonomía reglamentaria, presupuestaria y de gobierno de las Cámaras, y exige mayoría absoluta para aprobar o reformar sus Reglamentos internos. Esa mayoría absoluta es la garantía de que las normas del juego no se cambian en beneficio de una mayoría circunstancial, sino que requieren un consenso amplio.</p>', 7);
SET @seccion_id := LAST_INSERT_ID();


